// Leaf Map modeled by the ordered key list a construction path produces.
function leafMap(o) {
  return Object.keys(o).join('>');
}
function distinctLeaves(builder, n) {
  const seen = new Set();
  for (let i = 0; i < n; i++) seen.add(leafMap(builder(i)));
  return seen.size;
}

// STABLE: a, then b, then c -> one transition path -> one leaf Map.
function stable(i) {
  const o = {};
  o.a = i; o.b = i + 1; o.c = i + 2;
  return o;
}

// CHURNY: rotate which key is assigned first by index (3 orders),
// plus a late field on every other object (x2) -> 3 * 2 = 6 distinct branches.
function churny(i) {
  const o = {};
  const keys = ['a', 'b', 'c'];
  for (let k = 0; k < 3; k++) {
    const key = keys[(i + k) % 3];
    o[key] = 1;
  }
  if (i % 2 === 0) o.late = i; // late conditional field branches the tree further
  return o;
}

const stableLeaves = distinctLeaves(stable, 6);
const churnyLeaves = distinctLeaves(churny, 6);
console.log('stable=' + stableLeaves + ' churny=' + churnyLeaves);

function buildRow(raw) {
  const r = {};
  // keys arrive in arbitrary order from raw
  for (const k of Object.keys(raw)) r[k] = raw[k];
  // amount is sometimes an int, sometimes a float -> representation churn
  r.amount = raw.cents / (raw.fractional ? 100 : 1);
  return r;
}

model.en:
Build from a fixed schema in a constant key order, and pin the numeric field to one representation so it never has to generalize:<br><code>function buildRow(raw) {
  return {
    id: raw.id ?? null,
    name: raw.name ?? null,
    // always a Double: divide by 100 unconditionally so the field is never an integer Smi.
    amount: raw.cents / 100,
    currency: raw.currency ?? null,
  };
}</code><br>Key moves: (1) no <code>for...of Object.keys</code> assignment — assign every known field by name in one constant order, so all rows follow the same transition path to one leaf Map; (2) default missing fields to <code>null</code> instead of conditionally omitting them; (3) make <code>amount</code> consistently a Double (always divide by 100) so the field's representation is Double from the first instance and never generalizes mid-flight. One shape, stable representations, monomorphic read site.

model.ru:
Строй по фиксированной схеме в постоянном порядке ключей и закрепи числовое поле за одним representation, чтобы ему никогда не пришлось обобщаться:<br><code>function buildRow(raw) {
  return {
    id: raw.id ?? null,
    name: raw.name ?? null,
    // всегда Double: делим на 100 безусловно, чтобы поле никогда не было целым Smi.
    amount: raw.cents / 100,
    currency: raw.currency ?? null,
  };
}</code><br>Ключевые ходы: (1) никакого присваивания через <code>for...of Object.keys</code> — присваивай каждое известное поле по имени в одном постоянном порядке, чтобы все строки шли по одному пути переходов к одному листовому Map; (2) отсутствующие поля по умолчанию <code>null</code> вместо условного пропуска; (3) сделай <code>amount</code> стабильно Double (всегда деля на 100), чтобы representation поля был Double с первого экземпляра и никогда не обобщался на лету. Одна форма, стабильные representations, monomorphic точка чтения.
